import { Component, OnInit } from '@angular/core';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { SignupDataService } from 'src/app/services/signup/signup-data.service';


@Component({
  selector: 'app-signup',
  templateUrl: './signup.component.html',
  styleUrls: ['./signup.component.css']
})
export class SignupComponent implements OnInit{

  public form: FormGroup;

  constructor(
    private service: SignupDataService,
    private fb: FormBuilder,
    private router: Router)
  {
    this.form = this.fb.group({
      username: [
        '', Validators.compose([
          Validators.minLength(3),
          Validators.maxLength(20),
          Validators.required
        ])
      ],
      password: [
        '', Validators.compose([
          Validators.minLength(5),
          Validators.maxLength(50),
          Validators.required
        ])
      ],
      email: [
        '', Validators.compose([
          Validators.minLength(5),
          Validators.maxLength(150),
          Validators.required
        ])
      ],
    })
  }

  async ngOnInit(): Promise<void> {
  }

  async register(){
    this.service.registerUser(this.form.value).subscribe( (data: any) => {
      this.router.navigate(['/login']);
    },
    (err) => {
      console.log(err);
    } )
  }

}
<div class="uk-flex-center" uk-grid>
  <div class="uk-width-1-3@m">
    <p class="uk-text-center uk-margin-large-top uk-margin-medium-bottom">
      <span class="uk-icon uk-margin-small-right" uk-icon="icon: logo-color-dark; ratio: 0.7"></span>
    </p>


    <form [formGroup]="form">
      <div class="uk-card uk-card-primary uk-card-body uk-box-shadow-small">
        <h3 class="uk-card-title">Cadastre-se</h3>

        <div class="uk-margin">
          <input class="uk-input uk-form-large" formControlName="email" type="email" placeholder="Email"
          [ngClass]="{'uk-form-danger': (!form.controls['email'].valid)}">
        </div>

        <div class="uk-margin">
          <input class="uk-input uk-form-large" formControlName="username" type="text" placeholder="Username"
          [ngClass]="{'uk-form-danger': (!form.controls['username'].valid)}">
        </div>

        <div class="uk-margin">
          <input class="uk-input uk-form-large" formControlName="password" type="password" placeholder="Senha"
          [ngClass]="{'uk-form-danger': (!form.controls['password'].valid)}">
        </div>

        <div class="uk-margin uk-text-right">
          <button class="uk-button uk-button-default" (click)="register()">Cadastrar</button>
        </div>

      </div>
    </form>

    <p class="uk-text-center">
      <a [routerLink]="['/login']" class="uk-button uk-button-link">Voltar</a>
    </p>

  </div>
</div>
